/** The clinical privileges register — GET /api/v1/ot/privileges (who may call: holders of ot.status.view or ot.privilege.manage). */
export function listPrivileges(query?: { employee_id?: number | null; privilege?: "Surgery" | "Anaesthesia" | "PreAnaesthesiaAssessment" | "RecoveryDischarge" | "Prescribing" | "RestrictedPrescribing" | "MedicationAdministration" | "RadiologyReporting" | null; include_revoked?: boolean }): Promise<ClinicalPrivilegeOut[]> {
  return api<ClinicalPrivilegeOut[]>("GET", withQuery(`/ot/privileges`, query), undefined);
}

/** Grant a clinical privilege — POST /api/v1/ot/privileges (who may call: holders of ot.privilege.manage). */
export function grantPrivilege(body: PrivilegeGrantIn): Promise<ClinicalPrivilegeOut> {
  return api<ClinicalPrivilegeOut>("POST", `/ot/privileges`, body, { idempotent: true });
}

/** Change the scope, basis or end of a privilege — PATCH /api/v1/ot/privileges/{privilege_id} (who may call: holders of ot.privilege.manage). */
export function updatePrivilege(privilege_id: number, body: PrivilegeUpdateIn): Promise<ClinicalPrivilegeOut> {
  return api<ClinicalPrivilegeOut>("PATCH", `/ot/privileges/${privilege_id}`, body);
}

/** Revoke a clinical privilege — POST /api/v1/ot/privileges/{privilege_id}/revoke (who may call: holders of ot.privilege.manage). */
export function revokePrivilege(privilege_id: number, body: PrivilegeRevokeIn): Promise<ClinicalPrivilegeOut> {
  return api<ClinicalPrivilegeOut>("POST", `/ot/privileges/${privilege_id}/revoke`, body);
}

/** Search employees — GET /api/v1/hr/employees (who may call: holders of hr.employee.view). */
export function searchHrEmployees(query?: { q?: string | null; status?: string | null; department_id?: number | null; limit?: number }): Promise<EmployeeSearchItemOut[]> {
  return api<EmployeeSearchItemOut[]>("GET", withQuery(`/hr/employees`, query), undefined);
}

/** The written theatre policy as a PDF — GET /api/v1/ot/theatre-policy/pdf (who may call: holders of ot.clinical.view or ot.checklist.configure or ot.privilege.manage). */
export function theatrePolicyPdf(): Promise<unknown> {
  return api<unknown>("GET", `/ot/theatre-policy/pdf`, undefined);
}
